html:
{%- set settings = frappe.get_cached_doc("Trust Compliance Settings") -%}
{%- set reg = (settings.company_accounts | selectattr("company", "equalto", doc.company) | list | first) -%}
{%- set donor = frappe.get_cached_doc("Trust Donor", doc.donor) -%}
{%- set fund = frappe.get_cached_doc("Fund", doc.fund) -%}

<div class="receipt">
  <div class="head">
    <div class="org">{{ doc.company }}</div>
    {%- if reg and reg.registration_12ab %}
    <div class="sub">{{ _("Registered under Section 12A / 12AB:") }} {{ reg.registration_12ab }}</div>
    {%- endif %}
    {%- if reg and reg.trust_pan %}
    <div class="sub">{{ _("PAN:") }} {{ reg.trust_pan }}</div>
    {%- endif %}
  </div>

  <div class="title">{{ _("Receipt for Donation") }}</div>
  <div class="subtitle">
    {%- if reg and reg.registration_80g %}
      {{ _("Eligible for deduction under Section 80G of the Income-tax Act, 1961") }}<br>
      {{ _("80G Registration:") }} <b>{{ reg.registration_80g }}</b>
      {%- if reg.registration_80g_date %} {{ _("dated") }} {{ frappe.format(reg.registration_80g_date, {"fieldtype": "Date"}) }}{% endif %}
    {%- else %}
      <span class="warn">{{ _("80G registration number not configured - this receipt is not valid for a deduction claim.") }}</span>
    {%- endif %}
  </div>

  <table class="meta">
    <tr>
      <td><span class="lbl">{{ _("Receipt No") }}</span><br><b>{{ doc.receipt_no }}</b></td>
      <td><span class="lbl">{{ _("Date") }}</span><br><b>{{ frappe.format(doc.donation_date, {"fieldtype": "Date"}) }}</b></td>
      <td><span class="lbl">{{ _("Financial Year") }}</span><br><b>{{ doc.financial_year }}</b></td>
    </tr>
  </table>

  <table class="body">
    <tr>
      <td class="lbl">{{ _("Received with thanks from") }}</td>
      <td><b>{{ doc.donor_name if not doc.is_anonymous else _("Anonymous Donor") }}</b></td>
    </tr>
    {%- if donor.address and not doc.is_anonymous %}
    <tr><td class="lbl">{{ _("Address") }}</td><td>{{ donor.address }}</td></tr>
    {%- endif %}
    {%- if donor.pan and not doc.is_anonymous %}
    <tr><td class="lbl">{{ _("Donor PAN") }}</td><td>{{ donor.pan }}</td></tr>
    {%- endif %}
    <tr>
      <td class="lbl">{{ _("The sum of") }}</td>
      <td class="amount">{{ doc.get_formatted("amount") }}</td>
    </tr>
    <tr>
      <td class="lbl">{{ _("In words") }}</td>
      <td><i>{{ doc.amount_in_words }}</i></td>
    </tr>
    <tr>
      <td class="lbl">{{ _("By") }}</td>
      <td>{{ _(doc.mode) }}{% if doc.mode == "In Kind" and doc.in_kind_description %} - {{ doc.in_kind_description }}{% endif %}</td>
    </tr>
    <tr>
      <td class="lbl">{{ _("Towards") }}</td>
      <td>
        {{ fund.fund_name }}
        {%- if doc.is_corpus %} <span class="tag">{{ _("Corpus") }}</span>{% endif %}
        {%- if fund.is_fcra %} <span class="tag">{{ _("Foreign Contribution (FCRA)") }}</span>{% endif %}
        {%- if doc.purpose %}<br><span class="purpose">{{ doc.purpose }}</span>{% endif %}
      </td>
    </tr>
  </table>

  {%- if doc.is_corpus %}
  <div class="note">{{ _("This is a contribution towards the corpus of the Trust with a specific direction from the donor, and forms part of the capital of the Trust.") }}</div>
  {%- endif %}
  {%- if fund.is_fcra and reg and reg.registration_fcra %}
  <div class="note">{{ _("Received as foreign contribution under FCRA registration") }} {{ reg.registration_fcra }}.</div>
  {%- endif %}

  <table class="sign">
    <tr>
      <td>{{ _("Donor's copy") }}</td>
      <td class="right">
        <div class="line"></div>
        {%- if reg and reg.authorised_signatory %}
        <b>{{ reg.authorised_signatory }}</b><br>
        {%- endif %}
        {{ (reg.signatory_designation if reg and reg.signatory_designation else _("Authorised Signatory")) }}<br>
        {{ doc.company }}
      </td>
    </tr>
  </table>
</div>

<style>
.receipt { font-family: "Lato", "Helvetica Neue", Arial, sans-serif; color: #1a1a1a;
  max-width: 760px; margin: 0 auto; padding: 26px 30px; border: 1px solid #d8d8d8; }
.head { text-align: center; border-bottom: 2px solid #1a1a1a; padding-bottom: 10px; }
.org { font-family: "Playfair Display", Georgia, serif; font-size: 21px; font-weight: 700;
  letter-spacing: 0.2px; }
.sub { font-size: 10.5px; color: #555; margin-top: 2px; }
.title { font-family: "Playfair Display", Georgia, serif; font-size: 16px; font-weight: 700;
  text-align: center; margin: 16px 0 4px; text-transform: uppercase; letter-spacing: 1.2px; }
.subtitle { text-align: center; font-size: 10.5px; color: #444; line-height: 1.5; }
.warn { color: #a11; font-weight: 600; }
.meta { width: 100%; margin: 18px 0; border-collapse: collapse; }
.meta td { border: 1px solid #e0e0e0; padding: 7px 10px; font-size: 12px; width: 33.3%; }
.body { width: 100%; border-collapse: collapse; }
.body td { padding: 7px 4px; font-size: 12.5px; vertical-align: top; border-bottom: 1px dotted #e6e6e6; }
.lbl { color: #666; font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.6px;
  width: 175px; white-space: nowrap; }
.amount { font-size: 16px; font-weight: 700; }
.purpose { color: #555; font-size: 11.5px; }
.tag { display: inline-block; font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.6px;
  border: 1px solid #999; border-radius: 2px; padding: 1px 5px; margin-left: 4px; color: #444; }
.note { margin-top: 12px; font-size: 11px; color: #444; font-style: italic; }
.sign { width: 100%; margin-top: 34px; font-size: 11px; }
.sign td { vertical-align: bottom; }
.right { text-align: right; }
.line { border-top: 1px solid #333; width: 210px; margin-left: auto; margin-bottom: 5px; }
</style>
